public class Main {
    public static void main(String[] args) {
        int[] arr = new int[10];

        int sum = 0;
        int i = 0;

        for(i = 0; i < arr.length; i++) {
            arr[i] = 2 * i;
        }

        for(i = 0; i < arr.length; i++) {
            sum = sum + arr[i];
        }

        System.out.println("Sum = " + sum);
